final class MainnetTransaction {
  const MainnetTransaction({
    required this.description,
    required this.txid,
    required this.hex,
    required this.inputCount,
    required this.isCoinbase,
    required this.outputs,
  });

  final String description;
  final String txid;
  final String hex;
  final int inputCount;
  final bool isCoinbase;

  /// 표준 주소 형식이 아닌 출력(P2PK, bare multisig, OP_RETURN, anchor)은 address가 null
  final List<({int amount, String? address})> outputs;
}
